{
  "schema": "strategy-v1",
  "entrypoint": "strategy.py:decide",
  "warmup_bars": 169,
  "history_bars": 170,
  "responsibilities": {
    "code": "cup-v2 numeric screen, cup/handle geometry, deterministic shortlist, account eligibility, and cross-symbol breakout-strength priority",
    "model": "Assess the fixed cup/handle candidates under the approved cup, handle, and coherence rubrics; conditionally review every non-pass candidate once."
  },
  "account": {
    "mode": "risk-managed",
    "risk_fraction": 0.25,
    "max_weight": 1,
    "max_positions": 10,
    "entry_gap_limit": 0.01,
    "commission": 0.0005,
    "slippage": 0.0005,
    "progress_units": 1,
    "stagnation_sessions": 30,
    "trailing_stop_units": 0
  },
  "judgment": {
    "criteria": "Assess each candidate independently. Cup: decline, rounded bottom or sustained consolidation and recovery, not mainly a sharp V. Handle: smaller shallow consolidation near recovered upper rim. Coherence: one connected cup and handle. All three must pass; any fail fails; otherwise any insufficient evidence makes insufficient; otherwise pass. Cite visible dated evidence only in the fixed anchor regions. A steep drop or gap alone is not failure if a sustained base follows; breakout rises do not erase an earlier handle. Do not add numeric limits. Review each non-pass once; review prior reasoning/counterevidence but do not vote or force acceptance.",
    "trigger": "After numerical screening and account eligibility, assess each offered candidate; if any candidate is non-pass, conduct one conditional review for every non-pass candidate.",
    "tools": ["read_bars", "price_facts"],
    "uncertainty": "skip",
    "input_mode": "chart_and_text",
    "history_bars": 160,
    "chart_history": "declared",
    "review_nonpass": true,
    "repair_once": true,
    "rubric": {
      "cup": {
        "description": "Judge a decline, rounded bottom or sustained consolidation and recovery, not mainly a sharp V. Cite concise visible dated evidence within left_rim through right_rim. A steep drop or gap alone is not failure if a sustained base follows.",
        "start_anchor": "left_rim",
        "end_anchor": "right_rim"
      },
      "handle": {
        "description": "Judge a smaller shallow consolidation near the recovered upper rim. Cite concise visible dated evidence within handle_start through handle_end; exclude signal-day breakout evidence.",
        "start_anchor": "handle_start",
        "end_anchor": "handle_end"
      },
      "coherence": {
        "description": "Judge whether the cup and handle form one connected structure, not unrelated segments. Cite concise visible dated evidence within left_rim through handle_end.",
        "start_anchor": "left_rim",
        "end_anchor": "handle_end"
      }
    }
  }
}

